        "label": { "type": "literal" , "xml:lang": "en" , "value": "Massieu Function" } ,
        "description": { "type": "literal" , "datatype": "http://qudt.org/schema/qudt/LatexString" , "value": "The Massieu function, $\\Psi$, is defined as: $\\Psi = \\Psi (X_1, \\dots , X_i, Y_{i+1}, \\dots , Y_r\n    )$,  where for every system with degree of freedom $r$ one may choose $r$ variables, e.g. , to define a coordinate system,\n    where $X$ and $Y$ are extensive and intensive variables, respectively, and where at least one extensive variable must be\n    within this set in order to define the size of the system. The $(r + 1)^{th}$ variable,$\\Psi$ , is then called the Massieu\n    function.\n  " } ,
        "wikidata": { "type": "uri" , "value": "http://www.wikidata.org/entity/Q3077625" } ,
        "definedBy": { "type": "uri" , "value": "http://qudt.org/vocab/quantitykind" }
